  int count=0;
  for(int a=0;a<10;a++) for(int b=0;b<10;b++) for(int c=0;c<10;c++) {
    if(a==b || a==c || b==c) continue;
    char candidate[3]={'0'+a,'0'+b,'0'+c};
    int ok=1;
    for(int h=0;h<n && ok;h++) {
      int s=0, common=0;
      for(int i=0;i<3;i++) {
        if(candidate[i]==guesses[h][i]) s++;
